const body = $input.first().json.body || $input.first().json;
const message = (body.message || '').substring(0, 2000);
const source = body.source || 'chat_widget';
const url = body.url || '';

if (!message.trim()) {
  throw new Error('Empty message');
}

return [{ json: { message, source, url } }];

const response = $input.first().json;
const chatData = $('Extract Chat Message').first().json;

let classification;
try {
  const text = response.choices[0].message.content;
  classification = JSON.parse(text);
} catch(e) {
  classification = {
    category: 'FAQ',
    priority: 'P2',
    language: 'HR',
    summary: 'Could not parse classification',
    requires_human: true,
    suggested_action: 'Manual review needed',
    auto_reply: ''
  };
}

if (classification.summary) {
  classification.summary = classification.summary.substring(0, 200).replace(/[<>]/g, '');
}

return [{ json: { ...chatData, ...classification } }];

const d = $input.first().json;

const webhookMap = {
  MEDICAL: $env.SLACK_WEBHOOK_MEDICAL,
  ORDER:   $env.SLACK_WEBHOOK_ORDER,
  BUSINESS: $env.SLACK_WEBHOOK_BUSINESS,
  FAQ:     $env.SLACK_WEBHOOK_FAQ,
  URGENT:  $env.SLACK_WEBHOOK_URGENT
};

const emoji = { P1: '🚨', P2: '⚠️', P3: 'ℹ️' }[d.priority] || 'ℹ️';
const urgentPrefix = d.priority === 'P1' ? '🚨 *HITNO / URGENT* 🚨\n' : '';

const slackWebhook = webhookMap[d.category] || webhookMap['FAQ'];
const slackMessage = urgentPrefix +
  emoji + ' *Nova poruka — ' + d.category + '* (' + d.priority + ')\n' +
  '*Izvor:* Chat widget\n' +
  '*Poruka:* ' + d.message.substring(0, 300) + '\n' +
  '*Sažetak:* ' + d.summary + '\n' +
  '*Akcija:* ' + d.suggested_action + '\n' +
  '*Auto-odgovor:* ' + (d.requires_human ? 'Ne — čeka odgovor' : 'Da');

return [{ json: {
  ...d,
  slackWebhook,
  slackMessage,
  isP1: d.priority === 'P1'
} }];

